mapper.update:
UPDATE reviews
SET
	content = #{content},
	images = #{images, typeHandler=com.ssafy.gourming.typehandler.StringListJsonTypeHandler},
	rating_score = #{ratingScore},
	visited_at = #{visitedAt}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM reviews
WHERE id = #{reviewId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM reviews
WHERE place_id = #{placeId}

SELECT COUNT(*)
FROM reviews
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM popular_review_scores prs
WHERE prs.window_days = #{windowDays}
